# BEGIN EA_WORKER_MEMORY_DIAGNOSTICS_V3
MEMORY = {}


def _memory_snapshot(stage, **context):
    """Read only this worker's process metadata, not scientific source bodies."""
    with Path("/proc/self/status").open("rb") as stream:
        raw = stream.read(16385)
    if len(raw) > 16384:
        raise RuntimeError("EA_MEMORY_STATUS_METADATA_CAP")
    values = {}
    for line in raw.decode("ascii").splitlines():
        key, _, value = line.partition(":")
        if key in {"VmRSS", "VmHWM", "VmSize"}:
            fields = value.split()
            if len(fields) != 2 or fields[1] != "kB" or not fields[0].isdigit():
                raise RuntimeError("EA_MEMORY_STATUS_UNIT_OR_VALUE")
            values[key] = int(fields[0]) * 1024
    if set(values) != {"VmRSS", "VmHWM", "VmSize"}:
        raise RuntimeError("EA_MEMORY_STATUS_FIELDS_MISSING")
    with Path("/proc/self/statm").open("rb") as stream:
        statm = stream.read(1025)
    if len(statm) > 1024 or len(statm.split()) < 2:
        raise RuntimeError("EA_MEMORY_STATM_METADATA_CAP_OR_FIELDS")
    return {"pid": os.getpid(), "ppid": os.getppid(), "stage": stage,
            "observed_monotonic_seconds": time.monotonic(),
            "ru_maxrss_bytes": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * 1024,
            "current_status_VmRSS_bytes": values["VmRSS"], "current_mm_VmHWM_bytes": values["VmHWM"],
            "virtual_size_bytes": values["VmSize"],
            "current_statm_RSS_bytes": int(statm.split()[1]) * os.sysconf("SC_PAGE_SIZE"),
            "context": context}


def _memory_note(stage, **context):
    sample = _memory_snapshot(stage, **context)
    MEMORY[stage] = sample
    for name in ("ru_maxrss_bytes", "current_status_VmRSS_bytes", "current_mm_VmHWM_bytes", "current_statm_RSS_bytes"):
        MEMORY.setdefault("observed_maxima_bytes", {})[name] = max(
            MEMORY.get("observed_maxima_bytes", {}).get(name, 0), sample[name])
    return sample


def _memory_write(kind, extra=None):
    """At most one <=32KiB initial and one <=32KiB failure file per worker."""
    from workflows.data_v1_final.labels.streaming_cpu_v2.support import budget
    if kind not in {"initial", "failure"}:
        raise ValueError("EA_MEMORY_DIAGNOSTIC_KIND_NOT_BOUNDED")
    cfg, output = MEMORY["configuration"], MEMORY["output"]
    result = {"schema": "EA_WORKER_MEMORY_DIAGNOSTIC_V3", "kind": kind, "pid": os.getpid(),
              "worker_rss_stop_bytes_unchanged": cfg["worker_rss_stop_bytes"],
              "guard_basis_unchanged": "resource.getrusage(RUSAGE_SELF).ru_maxrss*1024",
              "metadata": {key: value for key, value in MEMORY.items() if key not in {"configuration", "output"}},
              "extra": extra, "scientific_values_or_scope_changed": False}
    body = (json.dumps(result, allow_nan=False, sort_keys=True) + "\n").encode()
    if len(body) > 32768:
        raise RuntimeError("EA_WORKER_MEMORY_DIAGNOSTIC_32KIB_CAP")
    budget(output, cfg["output_cap_bytes"] - len(body))
    path = output / ("worker_memory_v3_" + str(os.getpid()) + "." + kind + ".json")
    with path.open("xb") as stream:
        stream.write(body)
        stream.flush()
    budget(output, cfg["output_cap_bytes"])


def _memory_start(cfg, output):
    target = Path(output)
    allowed = Path(cfg["external_output_root"])
    if (not target.is_absolute() or allowed not in target.parents
            or any(p.is_symlink() for p in (target, *target.parents))
            or not target.is_dir() or target.stat().st_uid != os.getuid()):
        raise ValueError("EA_MEMORY_EVIDENCE_NOT_OWN_EXISTING_EXTERNAL_OUTPUT")
    MEMORY.update(configuration=cfg, output=target)
    _memory_note("initial_pre_arrow")
    _memory_write("initial")


def _memory_batches(iterable, pin, row_group):
    iterator = iter(iterable)
    index = 0
    while True:
        _memory_note("latest_pre_batch", source_path=pin["path"], row_group=row_group, batch_index=index)
        try:
            batch = next(iterator)
        except StopIteration:
            return
        yield batch
        index += 1


def project(partition):
    try:
        return _project(partition)
    except BaseException as exc:
        try:
            _memory_note("worker_exception")
            _memory_write("failure", {"exception": type(exc).__name__, "message": str(exc)[:2000],
                "original_rss_guard_raised": str(exc) == "EA_DIAGNOSTIC_WORKER_RSS_LIMIT"})
        except BaseException as diagnostic_exc:
            print("EA_WORKER_MEMORY_EVIDENCE_FAILED", os.getpid(), type(diagnostic_exc).__name__,
                  str(diagnostic_exc)[:1000], file=sys.stderr, flush=True)
        raise
# END EA_WORKER_MEMORY_DIAGNOSTICS_V3

def initialize(cfg, candidates, barrier, output):
    checkpoint()
    _memory_start(cfg, output)
